-- Rental assistance directory: Milwaukee organizations found by web research on 11/11/2026 that the first report missed,
-- plus corrections where the organizations' own pages say something newer. last_checked stays NULL (no one here has called them yet).
on conflict (code) do nothing;

select o.id, v.name, v.ht::text[], v.pops::text[], v.terms, null, v.pays, v.status, v.how, v.src
from (values
 ('WI-004','Subsistence aid','{rent,utility}','{veterans}','Lifetime cap reported as $5,000 or $7,500 (sources conflict; confirm with WDVA).',null,'open','County Veterans Service Office','https://dva.wi.gov/services/housing-and-financial-services/subsistence-aid-health-care-aid/'),
 ('MKE-054','Opportunity MKE (landlord incentives + deposit help)','{landlord_risk,deposit}','{general}','2024 flyer: $1,250 landlord sign-on bonus, referral bonus, holding fees, loss-mitigation fund beyond the deposit; voucher holders get deposit help. Current terms unconfirmed.','landlord','unclear','Fair Housing Council 414-278-1240','https://urbanmilwaukee.com/wp-content/uploads/2024/12/Opportunity-MKE_Housing-Provider-Flyer.pdf'),
 ('MKE-060','J-Help','{rent,flexible}','{general}','Temporary emergency fund for basic needs incl. rent; Jewish community and JFS clients. Confirm it still covers rent.',null,'unclear','JFS 414-390-5800','https://www.jfsmilw.org'),
 ('MKE-070','DV Housing First','{arrears,deposit,utility,flexible}','{dv}','Flexible money with case management; landlord mediation.',null,'open','The Asha Project 414-875-1511','https://www.unitedwaygmwc.org/Agencies/Asha-Family-Services.htm'),
 ('MKE-071','Prevention and diversion stipends','{rent,flexible}','{families}','Small emergency stipends and rental help outside winter.',null,'open','Adullam Outreach','https://www.unitedwaygmwc.org/Agencies/Adullam-Outreach.htm'),
 ('MKE-072','Reentry Housing Assistance','{deposit,rent}','{reentry,families}','Security deposit plus up to 3 months of rent for justice-impacted parents, with case management.',null,'open','My Way Out','https://unitedwaygmwc.org/Agencies/My-Way-Out.htm'),
 ('WI-008','One-time rental assistance / metro rent subsidy','{rent}','{native}','Enrolled Ho-Chunk members. An older annual report (2021-22) said up to $700, once a year.',null,'open','housing@ho-chunk.com','https://ho-chunknation.com/government/executive-branch/housing/'),
 ('WI-009','Energy emergency grant','{utility}','{general}','When WHEAP is denied or not enough.','utility','open','County energy assistance office','https://liheapch.ncat.org/node/1329'),
 ('WI-001','Emergency Assistance (eviction / homelessness)','{rent,deposit,first_month,arrears}','{families}','Families with children; income at or below 115% of poverty; assets up to $2,500. Amount not confirmed.',null,'open','ACCESS or the W-2 agency','https://dcf.wisconsin.gov/ea')
) as v(code, name, ht, pops, terms, pays, status, how, src)
join aid_orgs o on o.code = v.code
where not exists (select 1 from aid_programs p where p.org_id = o.id and p.name = v.name);

-- Corrections from the organizations' own pages (11/11/2026).
update aid_programs p set status = 'open', funds_today = 'unknown',
  terms = 'Reopened: CA page update dated 11/10/2026 says it will accept new applications. City of Milwaukee (county if funding allows), 18+, income loss in the past 30-90 days and current income, current lease plus 5-day notice or ledger, at or below 80% AMI, rent within FMR (eff. $985, 1BR $1,060, 2BR $1,263, 3BR $1,553, 4BR $1,664). Placard, fire and DV are priority.',
  how_to_apply = 'RHRC walk-in clinic, 728 N. James Lovell St. (renthelpmke.org), 414-895-7368',
  source_url = 'https://communityadvocates.net/what-we-do/rent-assistance-2026.html',
  note = 'Was paused 1/7/2026 (and city intake paused 8/2025). Call to confirm before referring.', updated_at = now()
from aid_orgs o where o.id = p.org_id and o.code = 'MKE-005' and p.name = 'City of Milwaukee rental assistance';
update aid_orgs set summary = 'Runs the Rental Housing Resource Center. Direct rent applications REOPENED per its 11/10/2026 page update (were paused 1/7/2026). Rent Bridge, Security Deposit Guarantee, WHEAP intake, DV shelter, PSH (Autumn West), Medicaid Housing Support Services.', updated_at = now() where code = 'MKE-005';
update aid_orgs set summary = 'HCV/Section 8: lottery 6/17/2026 picked 5,000 for the waitlist; HCV list now CLOSED and no vouchers being issued. Public Housing and Project-Based Voucher lists OPEN (confirm on RentCafe from 7/16/2026). HUD-VASH (258), RAD. Pays landlords directly.',
  source_url = 'https://www.hacm.org/for-residents/section-8-housing-choice-voucher-waiting-list-update-lottery-results/-fsiteid-1', updated_at = now() where code = 'MKE-002';
update aid_programs p set status = 'paused', terms = 'No NEW tenant-based vouchers in 2026 (budget cap); existing ones continue. June 2026: County Board approved $2.5M HOME TBRA for unsheltered people only.',
  source_url = 'https://county.milwaukee.gov/EN/County-Executive/News/Milwaukee-County-Board-Approves-Crowleys-Proposal-to-Provide-2.5-Million-in-Rental-Assistance-for-Unhoused-Individuals', updated_at = now()
from aid_orgs o where o.id = p.org_id and o.code = 'MKE-001' and p.name = 'Tenant-Based Rental Assistance (TBRA)';
update aid_orgs set staff_note = 'United Way says the Milwaukee Justice Center took over pre-filing eviction mediation in 2025 (MJC 414-278-3965). Check whether 414-939-8800 still reaches mediation.', updated_at = now() where code = 'MKE-026';
update aid_orgs set staff_note = 'Eviction Free MKE is funded year to year (2026: county $100,000 restored, city $100,000, Trillium grant). No 2027 funding found yet.', updated_at = now() where code = 'MKE-024';
