insert into aid_orgs (code, region, name, kinds, populations, summary, verification, website, phone, address, source_url, source_note) values
('WI-001','wisconsin','Wisconsin DCF – Emergency Assistance (state program)','{money}','{families}','One-time payment for low-income families with children facing homelessness, including after a 5-day or 14-day notice or eviction summons. Apply through ACCESS or the W-2 agency. Applying for EA stays the eviction case under state law.','verified_limited','https://dcf.wisconsin.gov/ea','855-757-4539',null,'https://dcf.wisconsin.gov/ea','Web research 11/11/2026'),
('WI-002','wisconsin','Wisconsin DOA – Energy, Housing & Community Resources (EHH, TBRA)','{funder}','{general}','State office funding local agencies for homelessness prevention, rapid re-housing and HAP, plus state TBRA. Tenants do not apply to it directly.','verified_limited','https://energyandhousing.wi.gov/Pages/AgencyResources/ehh-program.aspx',null,null,'https://energyandhousing.wi.gov/Pages/AgencyResources/ehh-program.aspx','Web research 11/11/2026'),
('WI-003','wisconsin','Wisconsin DHS – Medicaid Housing Support Services','{navigation}','{families}','Medicaid-funded housing consultation, transition/relocation and tenancy-sustaining help for households with children or a pregnant member under 200% of poverty who are homeless or at risk. Delivered in Milwaukee by Community Advocates.','verified_limited','https://www.dhs.wisconsin.gov/medicaid/housing-supports.htm',null,null,'https://www.dhs.wisconsin.gov/medicaid/housing-supports.htm','Web research 11/11/2026'),
('WI-004','wisconsin','Wisconsin Dept. of Veterans Affairs – Assistance to Needy Veterans (subsistence aid)','{money}','{veterans}','Limited grant for veterans in need who have used other sources: current rent or mortgage, utilities. Apply through the County Veterans Service Officer.','verified_limited','https://dva.wi.gov/services/housing-and-financial-services/subsistence-aid-health-care-aid/',null,null,'https://dva.wi.gov/services/housing-and-financial-services/subsistence-aid-health-care-aid/','Web research 11/11/2026'),
('MKE-050','milwaukee','Milwaukee County Veterans Service Office','{access}','{veterans}','Helps veterans apply for state WDVA aid grants (including subsistence/rent aid) and other benefits.','verified_limited','https://county.milwaukee.gov/EN/Veterans-Services','414-266-1234',null,'https://county.milwaukee.gov/EN/Veterans-Services','Web research 11/11/2026'),
('WI-005','wisconsin','Wisconsin DATCP – Consumer Protection (landlord-tenant)','{legal}','{general}','Takes landlord-tenant complaints (security deposits, ATCP 134) and publishes the Landlord-Tenant Guide. No money.','verified_limited','https://datcp.wi.gov','800-422-7128',null,'https://datcp.wi.gov','Web research 11/11/2026'),
('WI-006','wisconsin','Wisconsin DWD – Equal Rights Division (housing discrimination)','{legal}','{general,disability}','Housing discrimination complaints, including disability; file within one year.','verified_limited','https://dwd.wisconsin.gov/er/',null,null,'https://dwd.wisconsin.gov/er/','Web research 11/11/2026'),
('MKE-051','milwaukee','City of Milwaukee – Community Development Grants Administration / Housing Trust Fund','{funder}','{general}','Awards CDBG, HOME and HOME-ARP to nonprofits; the Housing Trust Fund mainly funds supportive housing. 2026 HOME-ARP solicitation also covered TBRA.','verified_limited','https://city.milwaukee.gov/CDGA',null,null,'https://city.milwaukee.gov/CDGA','Web research 11/11/2026'),
('MKE-052','milwaukee','City of Milwaukee DNS – Landlord Training Program / Rent for Success','{landlord}','{general}','Free landlord training (screening, management) with MPD; Rent for Success is a free tenant-education class. No money.','verified_limited','https://city.milwaukee.gov/lltp','414-286-8122',null,'https://city.milwaukee.gov/Rent','Web research 11/11/2026'),
('MKE-053','milwaukee','South Milwaukee Housing Authority (CDA)','{subsidy,housing}','{general,seniors}','Public housing and a small Section 8 program (about 60 vouchers) in South Milwaukee. Waitlist status conflicts between sources: call.','needs_confirmation',null,'414-762-4114','2906 6th Ave., South Milwaukee','https://affordablehousingonline.com/housing-authority/Wisconsin/Housing-Authority-of-the-City-of-South-Milwaukee/WI008','Web research 11/11/2026 (aggregator only)'),
